// READ ONLY: capture actual canonical browser core direction logic inputs.
// No D.json or structural state is regenerated by this exporter.
import {chromium} from 'playwright';
import fs from 'node:fs';
import crypto from 'node:crypto';

const output=process.argv[2]||'/tmp/STRUCTURAL_RULE_REPLAY.json';
const url=process.env.GMFQ_DASHBOARD_URL||'http://127.0.0.1:8000/';
const browser=await chromium.launch({headless:true});
try{
  const page=await browser.newPage({viewport:{width:1440,height:900}});
  const errors=[];
  page.on('pageerror',e=>errors.push(String(e?.message||e)));
  await page.goto(url,{waitUntil:'domcontentloaded',timeout:120000});
  await page.waitForFunction(()=>
    typeof deriveCurrencyState==='function'&&
    typeof derivePairDecisionFrame==='function'&&
    typeof currencyIntelData==='object'&&
    typeof D==='object'&&Array.isArray(D.pairs)&&D.pairs.length===28,
    null,{timeout:120000});
  await page.waitForTimeout(2500);
  const state=await page.evaluate(()=>{
    const ccys=['USD','EUR','GBP','JPY','CHF','CAD','AUD','NZD'];
    const copy=x=>JSON.parse(JSON.stringify(x));
    const currencies={};
    for(const c of ccys){
      const d=currencyIntelData[c],actual=deriveCurrencyState(c);
      if(!d||!actual)throw Error('Currency source missing '+c);
      currencies[c]={
        raw_layers:{
          macro:copy(d.macro),rates:copy(d.rates),cb:copy(d.cb),
          liquidity:copy(d.liq),price:copy(d.price)
        },
        structural_engine:{macro:actual.macro,policy:actual.policy,base:actual.base,
          policy_context:actual.policyContext},
        historical_D_scores:{
          growth:D.macro[c]?.growth,labour:D.macro[c]?.labour,
          inflation:D.macro[c]?.inflation,cycle:D.macro[c]?.cycle},
        embedded_D_rate2y:D.macro[c]?.rate2y??null,
        dated_source_for_directional_labels:null
      };
    }
    const pairs={};
    for(const {pair} of D.pairs){
      const key=String(pair).replace('/','');
      if(pairs[key])throw Error('Duplicate pair '+key);
      const f=derivePairDecisionFrame(pair);
      pairs[key]={canonical_pair:pair,favored:f.fav,quality:f.quality,
        structural:copy(f.structural)};
    }
    return {
      schema:'GMFQ_CANONICAL_STRUCTURAL_RULE_REPLAY_V1',
      model_asof:D.asOf,price_asof:D.prices?.at(-1)?.Date||null,
      status:'HISTORICAL_DIRECTIONAL_RULES_AUDITED_NOT_MACRO_REBASED',
      currency_count:Object.keys(currencies).length,
      pair_count:Object.keys(pairs).length,
      scores_reconstructed:false,
      macro_rebase_permitted:false,
      raw_labels_dated_independently:false,
      economic_score_weights_present:false,
      currencies,pairs
    };
  });
  const signatures=await page.evaluate(()=>({
    polarity:layerPolarity.toString(),
    policy:policyFamilyPolarity.toString(),
    currency:deriveCurrencyState.toString(),
    pair:derivePairDecisionFrame.toString()
  }));
  state.engine_functions_sha256=Object.fromEntries(
    Object.entries(signatures).map(([key,body])=>[key,crypto.createHash('sha256').update(body).digest('hex')]));
  state.page_errors=errors;
  if(errors.length)throw Error('Browser errors: '+errors.join(' | '));
  fs.writeFileSync(output,JSON.stringify(state,null,2)+'\n');
  console.log(JSON.stringify({status:'CANONICAL_STRUCTURAL_TRACE_EXPORTED',
    model_asof:state.model_asof,pair_count:state.pair_count,
    currencies:state.currency_count,scores_reconstructed:false,output}));
}finally{await browser.close();}
